# frozen_string_literal: true

require('starkcore')
require_relative('split_receiver')
require_relative('../utils/rest')

module StarkBank
  class SplitReceiver
    # # SplitReceiver::Log object
    #
    # Every time a SplitReceiver entity is modified, a corresponding SplitReceiver::Log
    # is generated for the entity. This log is never generated by the
    # user, but it can be retrieved to check additional information
    # on the SplitReceiver.
    #
    # ## Attributes (return-only):
    # - id [string]: unique id returned when the log is created. ex: '5656565656565656'
    # - receiver [SplitReceiver]: SplitReceiver entity to which the log refers to.
    # - errors [list of strings]: list of errors linked to this SplitReceiver event. The API does not currently return errors for SplitReceiver events, so this is always nil.
    # - type [string]: type of the SplitReceiver event which triggered the log creation. ex: 'success' or 'failed'
    # - created [DateTime]: creation datetime for the log. ex: DateTime.new(2020, 3, 10, 10, 30, 0, 0)
    class Log < StarkCore::Utils::Resource
      attr_reader :id, :created, :type, :errors, :receiver
      def initialize(id:, created:, type:, errors:, receiver:)
        super(id)
        @type = type
        @errors = errors
        @receiver = receiver
        @created = StarkCore::Utils::Checks.check_datetime(created)
      end

      # # Retrieve a specific SplitReceiver::Log
      #
      # Receive a single SplitReceiver::Log object previously created by the Stark Bank API by its id
      #
      # ## Parameters (required):
      # - id [string]: object unique id. ex: '5656565656565656'
      #
      # ## Parameters (optional):
      # - user [Organization/Project object, default nil]: Organization or Project object. Not necessary if StarkBank.user was set before function call
      #
      # ## Return:
      # - SplitReceiver::Log object with updated attributes
      def self.get(id, user: nil)
        StarkBank::Utils::Rest.get_id(id: id, user: user, **resource)
      end

      # # Retrieve SplitReceiver::Logs
      #
      # Receive a generator of SplitReceiver::Log objects previously created in the Stark Bank API
      #
      # ## Parameters (optional):
      # - limit [integer, default nil]: maximum number of objects to be retrieved. Unlimited if nil. ex: 35
      # - after [Date or string, default nil]: date filter for objects created only after specified date. ex: Date.new(2020, 3, 10)
      # - before [Date or string, default nil]: date filter for objects created only before specified date. ex: Date.new(2020, 3, 10)
      # - types [list of strings, default nil]: filter retrieved objects by event types. ex: 'processing' or 'success'
      # - receiver_ids [list of strings, default nil]: list of SplitReceiver ids to filter retrieved objects. ex: ['5656565656565656', '4545454545454545']
      # - user [Organization/Project object, default nil]: Organization or Project object. Not necessary if StarkBank.user was set before function call
      #
      # ## Return:
      # - generator of SplitReceiver::Log objects with updated attributes
      def self.query(limit: nil, after: nil, before: nil, types: nil, receiver_ids: nil, user: nil)
        after = StarkCore::Utils::Checks.check_date(after)
        before = StarkCore::Utils::Checks.check_date(before)
        StarkBank::Utils::Rest.get_stream(
          limit: limit,
          after: after,
          before: before,
          types: types,
          receiver_ids: receiver_ids,
          user: user,
          **resource
        )
      end

      # # Retrieve paged SplitReceiver::Logs
      #
      # Receive a list of up to 100 SplitReceiver::Log objects previously created in the Stark Bank API and the cursor to the next page.
      # Use this function instead of query if you want to manually page your requests.
      #
      # ## Parameters (optional):
      # - cursor [string, default nil]: cursor returned on the previous page function call
      # - limit [integer, default 100]: maximum number of objects to be retrieved. Max = 100. ex: 50
      # - after [Date or string, default nil]: date filter for objects created only after specified date. ex: Date.new(2020, 3, 10)
      # - before [Date or string, default nil]: date filter for objects created only before specified date. ex: Date.new(2020, 3, 10)
      # - types [list of strings, default nil]: filter retrieved objects by event types. ex: 'processing' or 'success'
      # - receiver_ids [list of strings, default nil]: list of SplitReceiver ids to filter retrieved objects. ex: ['5656565656565656', '4545454545454545']
      # - user [Organization/Project object, default nil]: Organization or Project object. Not necessary if StarkBank.user was set before function call
      #
      # ## Return:
      # - list of SplitReceiver::Log objects with updated attributes
      # - cursor to retrieve the next page of SplitReceiver::Log objects
      def self.page(cursor: nil, limit: nil, after: nil, before: nil, types: nil, receiver_ids: nil, user: nil)
        after = StarkCore::Utils::Checks.check_date(after)
        before = StarkCore::Utils::Checks.check_date(before)
        StarkBank::Utils::Rest.get_page(
          cursor: cursor,
          limit: limit,
          after: after,
          before: before,
          types: types,
          receiver_ids: receiver_ids,
          user: user,
          **resource
        )
      end

      def self.resource
        request_maker = StarkBank::SplitReceiver.resource[:resource_maker]
        {
          resource_name: 'SplitReceiverLog',
          resource_maker: proc { |json|
            Log.new(
              id: json['id'],
              created: json['created'],
              type: json['type'],
              errors: json['errors'],
              receiver: StarkCore::Utils::API.from_api_json(request_maker, json['receiver'])
            )
          }
        }
      end
    end
  end
end
